<template>
  <article class="share-card">
    <header class="report-header"><div><span class="eyebrow">燕云十六声 · 配装档案</span><h1>{{ title || '我的燕云配装' }}</h1></div><div class="school-seal"><strong>{{ config.流派 }}{{ config.变体 }}</strong></div></header>
    <section class="attack-hero"><div class="hero-main"><span class="section-label">外功攻击</span><strong :class="{ inverted: externalAttack.min > externalAttack.max }"><small v-if="externalAttack.min > externalAttack.max">最小</small>{{ 整数(externalAttack.min) }}<i>{{ externalAttack.min > externalAttack.max ? "/" : "～" }}</i><small v-if="externalAttack.min > externalAttack.max">最大</small>{{ 整数(externalAttack.max) }}</strong></div><div class="native-attack" v-if="nativeAttack"><span>{{ nativeAttack.key }}攻击</span><strong>{{ 显示攻击(nativeAttack) }}</strong></div><div class="hero-dimensions"><span v-for="key in ['劲','敏','势']" :key="key">{{ key }} <b>{{ 整数(data.raw[key]) }}</b></span></div></section>
    <section class="judgement"><div class="section-heading"><h2>判定属性</h2><span>有效值</span></div><div class="share-rates"><div v-for="rate in data.rates" :key="rate.key"><div class="share-ring"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="42" fill="none" stroke="#ded8c8" stroke-width="5"/><circle cx="50" cy="50" r="42" fill="none" :stroke="rate.color" stroke-width="5" stroke-linecap="round" pathLength="100" :stroke-dasharray="`${rate.ratio} 100`" transform="rotate(-90 50 50)"/></svg><strong>{{ 百分比(rate.effective) }}</strong></div><h3>白字{{ rate.key }}</h3><span>{{ 百分比(rate.value) }}<small v-if="rate.overflow" class="overflow">(↑{{ 百分比(rate.overflow) }})</small></span></div></div><div v-if="data.direct.length" class="share-direct"><span v-for="rate in data.direct" :key="rate.key">{{ rate.key }} <b>{{ 百分比(rate.value) }}</b></span></div></section>
    <section class="build-section"><div class="section-heading"><h2>流派配装</h2><span>心法 · 套装</span></div><div class="heart-list"><div v-for="book in config.心法列表" :key="book" :class="quality(book)"><small>{{ 心法记录[book]?.品质 || '心法' }}</small><strong>{{ book }}</strong></div><span v-if="!config.心法列表.length">未配置心法</span></div><div class="set-row"><div><span>弓玦</span><strong>{{ 取套装('弓决',config.套装选择.弓决)?.名称 || '未选择' }}</strong></div><div><span>武器套装</span><strong>{{ 取套装('武器',config.套装选择.武器)?.名称 || '未选择' }}</strong></div></div></section>
    <section><div class="section-heading"><h2>增伤与穿透</h2><span>金色为有效值</span></div><div class="report-modifiers"><div v-for="item in data.modifiers" :key="item.key"><span class="modifier-school" :aria-hidden="!item.schoolName">{{ item.schoolName }}</span><div class="modifier-line"><span>{{ item.moveName }}</span><strong>{{ 显示增益(item) }} <b v-if="item.effective !== undefined">({{ 显示增益(item,true) }})</b></strong></div><div v-if="item.max" class="share-track"><i :style="{width: item.ratio+'%'}"></i></div></div></div><div v-if="full && otherAttacks.length" class="other-attacks"><span v-for="a in otherAttacks" :key="a.key">{{ a.key }}攻击 <strong>{{ 显示攻击(a) }}</strong></span></div></section>
    <section v-if="full" class="gear-section"><div class="section-heading"><h2>装备详录</h2><span>宫商角徵羽 · 定音</span></div><div class="equipment-report"><div v-for="group in gearGroups" :key="group[0]" class="gear-column"><div v-for="part in group" :key="part" class="report-equipment"><h3>{{ names[part] || part }}<span>{{ school?.武器[part] || '' }}</span><small v-if="config.装备词条[part]?.承音">承音</small></h3><div v-for="tone in Object.values(词条槽)" :key="tone" class="report-tone"><b :class="tone==='宫' ? 'tone-gold' : tone==='定音' ? 'tone-green' : 'tone-blue'">{{ tone }}</b><span>{{ config.装备词条[part]?.[tone]?.名称 || '未配置' }}</span><strong>{{ config.装备词条[part]?.[tone]?.名称 ? 格式化词条(config.装备词条[part][tone].名称,config.装备词条[part][tone].值) : '—' }}</strong></div></div></div></div></section>
    <footer><strong>燕云面板模拟器</strong><span>{{ date }} · {{ 数据.元数据.数据版本 }}</span></footer>
  </article>
</template>
<script setup>
import { computed } from 'vue'
import { 取面板展示, 整数, 百分比, 显示增益, 显示攻击 } from '../domain/panelDisplay.js'
import { 词条槽, 格式化词条 } from '../data/affinities.js'
import { 心法记录 } from '../data/xinfa.js'
import { 取套装 } from '../data/sets.js'
import { 取流派配置 } from '../data/schools.js'
import 数据 from '../data/game/规则.json'
const props=defineProps({config:Object,title:String,full:Boolean})
const data=computed(()=>取面板展示(props.config))
const school=computed(()=>取流派配置(props.config.流派,props.config.变体))
const externalAttack=computed(()=>data.value.attacks.find(a=>a.key==='外功'))
const nativeAttack=computed(()=>data.value.attacks.find(a=>a.key===data.value.panel.本系属性))
const otherAttacks=computed(()=>data.value.attacks.filter(a=>!['外功',data.value.panel.本系属性].includes(a.key)))
const date=new Date().toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'})
const names={头:'冠胄',胸:'胸甲'}
const gearGroups=[['主武器','副武器','环','佩'],['头','胸','胫甲','腕甲']]
function quality(name){return 'book-'+({金色:'gold',紫色:'purple',蓝色:'blue'}[心法记录[name]?.品质] || 'unknown')}
</script>
